--  KH IL VOSTRO CAFFÈ — استيراد أصناف المنيو إلى القاعدة
--
--  المصدر: index.html (صفحة الرابط) — الأسعار منسوخة حرفيًا.
--  التشغيل: Supabase → SQL Editor → الصق هذا الملف → Run
--  آمن للتشغيل أكثر من مرة (يحدّث بدل التكرار).
--
--  ⚠️ لا أعد تشغيله بعد أن يبدأ المدير بتعديل الأسعار من لوحة الإدارة،
--     وإلا ستُرجع التعديلات إلى قيم المنيو الثابتة.
--
--  الأصناف: 118   ·   التصنيفات: breakfast, coldcoffee, dolci, eveningbox, frappe, hotcoffee, juices, mojito, slush, smoothieshake, tropical
--  الأنواع: سعر مفرد 88 · خيارات/تشكيلات 27 · بوكس 3
--  المعرّفات الجديدة التي يضيفها الإدارة تبدأ من 900000.
-- ============================================================================

begin;

on conflict (id) do update set
  ar         = excluded.ar,
  it         = excluded.it,
  category   = excluded.category,
  sub        = excluded.sub,
  price      = excluded.price,
  price_text = excluded.price_text,
  options    = excluded.options,
  image      = excluded.image,
  updated_at = now();

commit;

